#include <vector>
#include <numeric>

class Solution {
public:
    long long minTransformOperations(std::vector<int>& nums) {
        long long n = nums.size();
        long long total = std::accumulate(nums.begin(), nums.end(), 0LL);
        if (total % n != 0) return -1;

        long long target = total / n;
        long long pos_diff = 0;
        for (int x : nums) {
            if (x > target) pos_diff += x - target;
        }
        return pos_diff;
    }
};

class Solution {
    public long minTransformOperations(int[] nums) {
        long n = nums.length;
        long total = 0;
        for (int x : nums) total += x;
        if (total % n != 0) return -1;

        long target = total / n;
        long posDiff = 0;
        for (int x : nums) {
            if (x > target) posDiff += x - target;
        }
        return posDiff;
    }
}

function minTransformOperations(nums) {
    const n = nums.length;
    let total = 0;
    for (const x of nums) total += x;
    if (total % n !== 0) return -1;

    const target = Math.floor(total / n);
    let posDiff = 0;
    for (const x of nums) {
        if (x > target) posDiff += x - target;
    }
    return posDiff;
}
